FDropRow UOptionalLibrary::GetDropRow(int32 Key, bool& bFound)
{
    const FDropRow* Found = FOptional::Drop().FindByIndex(Key);

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FDropRow();
}

int32 UOptionalLibrary::GetDropRowCount()
{
    return FOptional::Drop().Records().Num();
}

FDropRow UOptionalLibrary::GetDropRowAt(int32 Position, bool& bFound)
{
    const TArray<FDropRow>& Rows = FOptional::Drop().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FDropRow();
}


bool UOptionalLibrary::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    return FOptional::ReadAll(BasePath, FileExtension);
}

bool FOptional::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    // Read into tables of their own and moved into place at the end. Reading again is a
    // refresh - a patched .pak, a downloaded table - and one that fails on the third file
    // must not leave the first two replaced and the rest as they were.
    FDropTable LoadedDrop;

    if (!LoadedDrop.Read(FPaths::Combine(BasePath, TEXT("Drop") + FileExtension)))
    {
        return false;
    }

    DropStorage = MoveTemp(LoadedDrop);

    return true;
}
